<script setup lang="ts">
import { ref } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import { blankResume, compactResume, getResumes, normalizeTemplateId, saveResume } from '@/utils/resume'
import type { ResumeData, ResumeEntry } from '@/utils/resume'
const form = ref<ResumeData>(blankResume())
const summary = (entry: ResumeEntry, keys: string[]) => keys.map(key => entry[key]).filter(Boolean).join(' | ')
onLoad((q) => { const data = q?.id ? getResumes().find(i => i.id === q.id) : blankResume(normalizeTemplateId(String(q?.templateId || 'classic'))); form.value = JSON.parse(JSON.stringify(data || blankResume())); uni.setStorageSync('resume-draft', form.value) })
onShow(() => { const draft = uni.getStorageSync('resume-draft'); if (draft) form.value = draft })
function open(url: string) { uni.navigateTo({ url }) }
function entryIndex(field: 'education' | 'work' | 'projects', item: ResumeEntry) { return form.value[field].indexOf(item) }
function deleteField(field: 'summary' | 'skills') { form.value[field] = ''; uni.setStorageSync('resume-draft', form.value) }
function deleteEntry(field: 'education' | 'work' | 'projects', index: number) { form.value[field].splice(index, 1); uni.setStorageSync('resume-draft', form.value) }
function preview() { uni.setStorageSync('resume-preview', form.value); uni.navigateTo({ url: '/pages/resume-preview/resume-preview' }) }
function save() { if (!form.value.name.trim()) return uni.showToast({ title: '请先完善基本信息', icon: 'none' }); saveResume(form.value); uni.removeStorageSync('resume-draft'); uni.showToast({ title: '保存成功', icon: 'success' }); setTimeout(() => uni.switchTab({ url: '/pages/me/me' }), 500) }
</script>
<template><scroll-view scroll-y class="page"><view class="modules"><view class="module-title"><text>基本信息</text></view><view class="card basic" @click="open('/pages/resume-basic/resume-basic')"><view><text class="primary">{{form.name||'点击填写个人信息'}}</text><text v-if="form.phone" class="secondary">电话：{{form.phone}}</text><text v-if="form.email" class="secondary">邮箱：{{form.email}}</text><text v-if="form.intention" class="secondary">求职：{{form.intention}}</text></view><text class="arrow">›</text></view><view class="module-title"><text>个人总结</text><text v-if="form.summary" class="delete" @click.stop="deleteField('summary')">删除</text></view><view class="card" @click="open('/pages/resume-text/resume-text?field=summary')"><text class="excerpt">{{form.summary||'点击填写自我评价与职业优势'}}</text><text class="arrow">›</text></view><view class="module-title"><text>工作经历</text><text class="plus" @click.stop="open('/pages/resume-experience/resume-experience?type=work&index=-1')">＋</text></view><view v-for="(item,i) in compactResume(form).work" :key="i" class="card item" @click="open(`/pages/resume-experience/resume-experience?type=work&index=${entryIndex('work',item)}`)"><view><text class="primary">{{item.company}}</text><text class="secondary">{{summary(item,['role','time'])}}</text></view><view class="item-actions"><text class="delete" @click.stop="deleteEntry('work',entryIndex('work',item))">删除</text><text class="arrow">›</text></view></view><view v-if="!compactResume(form).work.length" class="card empty-card" @click="open('/pages/resume-experience/resume-experience?type=work&index=-1')">添加工作经历</view><view class="module-title"><text>项目经历</text><text class="plus" @click.stop="open('/pages/resume-experience/resume-experience?type=projects&index=-1')">＋</text></view><view v-for="(item,i) in compactResume(form).projects" :key="i" class="card item" @click="open(`/pages/resume-experience/resume-experience?type=projects&index=${entryIndex('projects',item)}`)"><view><text class="primary">{{item.name}}</text><text class="secondary">{{summary(item,['role','time'])}}</text></view><view class="item-actions"><text class="delete" @click.stop="deleteEntry('projects',entryIndex('projects',item))">删除</text><text class="arrow">›</text></view></view><view v-if="!compactResume(form).projects.length" class="card empty-card" @click="open('/pages/resume-experience/resume-experience?type=projects&index=-1')">添加项目经历</view><view class="module-title"><text>教育经历</text><text class="plus" @click.stop="open('/pages/resume-experience/resume-experience?type=education&index=-1')">＋</text></view><view v-for="(item,i) in compactResume(form).education" :key="i" class="card item" @click="open(`/pages/resume-experience/resume-experience?type=education&index=${entryIndex('education',item)}`)"><view><text class="primary">{{item.school}}</text><text class="secondary">{{summary(item,['major','time'])}}</text></view><view class="item-actions"><text class="delete" @click.stop="deleteEntry('education',entryIndex('education',item))">删除</text><text class="arrow">›</text></view></view><view v-if="!compactResume(form).education.length" class="card empty-card" @click="open('/pages/resume-experience/resume-experience?type=education&index=-1')">添加教育经历</view><view class="module-title"><text>技能特长</text><text v-if="form.skills" class="delete" @click.stop="deleteField('skills')">删除</text></view><view class="card" @click="open('/pages/resume-text/resume-text?field=skills')"><text class="excerpt">{{form.skills||'点击填写专业技能与个人特长'}}</text><text class="arrow">›</text></view><view class="actions"><button class="preview" @click="preview">预览</button><button class="save" @click="save">保存简历</button></view></view></scroll-view></template>
<style scoped lang="scss">.page{min-height:100vh;background:#f5f6fa}.modules{padding:16px 16px 36px}.module-title{display:flex;align-items:center;margin:22px 2px 10px;color:#202938;font-size:18px;font-weight:700}.module-title:first-child{margin-top:2px}.dot{display:flex;width:25px;height:25px;align-items:center;justify-content:center;margin-right:8px;border-radius:50%;background:#2563eb;color:#fff;font-size:11px}.plus{margin-left:auto;color:#94a3b8;font-size:24px;font-weight:400}.delete{margin-left:auto;color:#ef4444;font-size:12px;font-weight:400}.item-actions{display:flex;align-items:center}.item-actions .delete{margin-left:0}.card{display:flex;min-height:72px;align-items:center;justify-content:space-between;box-sizing:border-box;padding:17px 16px;background:#fff;border-radius:12px;box-shadow:0 3px 14px rgb(30 58 138 / 4%)}.card+.card{margin-top:10px}.primary,.secondary{display:block}.primary{color:#172033;font-size:16px;font-weight:700}.secondary{margin-top:7px;color:#64748b;font-size:13px}.arrow{margin-left:12px;color:#9aa5b3;font-size:28px}.excerpt{display:-webkit-box;overflow:hidden;color:#596273;font-size:14px;line-height:23px;-webkit-box-orient:vertical;-webkit-line-clamp:2}.empty-card{justify-content:center;color:#2563eb;font-size:14px}.actions{display:flex;gap:10px;margin-top:28px}.actions button{flex:1;height:48px;border-radius:24px;line-height:48px}.preview{border:1px solid #2563eb;background:#eff6ff;color:#2563eb}.save{background:#2563eb;color:#fff}</style>
